import java.util.*;

class Solution {
  public int maximumSafenessFactor(List<List<Integer>> grid) {
    int n = grid.size();
    int[][] d = new int[n][n];
    for (int[] r : d) Arrays.fill(r, -1);
    ArrayDeque<int[]> q = new ArrayDeque<>();
    for (int i = 0; i < n; i++)
      for (int j = 0; j < n; j++)
        if (grid.get(i).get(j) == 1) {
          d[i][j] = 0;
          q.add(new int[] {i, j});
        }
    int[] dr = {-1, 1, 0, 0}, dc = {0, 0, -1, 1};
    while (!q.isEmpty()) {
      int[] u = q.remove();
      for (int k = 0; k < 4; k++) {
        int r = u[0] + dr[k], c = u[1] + dc[k];
        if (r >= 0 && r < n && c >= 0 && c < n && d[r][c] < 0) {
          d[r][c] = d[u[0]][u[1]] + 1;
          q.add(new int[] {r, c});
        }
      }
    }
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
    boolean[][] used = new boolean[n][n];
    pq.add(new int[] {d[0][0], 0, 0});
    while (!pq.isEmpty()) {
      int[] u = pq.remove();
      if (used[u[1]][u[2]]) continue;
      used[u[1]][u[2]] = true;
      if (u[1] == n - 1 && u[2] == n - 1) return u[0];
      for (int k = 0; k < 4; k++) {
        int r = u[1] + dr[k], c = u[2] + dc[k];
        if (r >= 0 && r < n && c >= 0 && c < n && !used[r][c])
          pq.add(new int[] {Math.min(u[0], d[r][c]), r, c});
      }
    }
    return 0;
  }
}
